/** Replace the entity type and columns. Reads are server-paged; detail uses the selected row.
 * Longer text stays in the Sheet. The alternate SplitView below uses the same page of rows.
 */
import { createRoot } from 'react-dom/client';
import {
  AlertCard,
  Badge,
  Button,
  Card,
  CardContent,
  EmptyState,
  FilterBar,
  Input,
  PageHeader,
  Prose,
  Section,
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
  Skeleton,
  SplitView,
  Stack,
  SurfaceApp,
  Table,
  TooltipContent,
  TooltipProvider,
  TooltipRoot,
  TooltipTrigger,
  parseAsEnum,
  parseAsFilters,
  parseAsInteger,
  parseAsString,
  useEntityQuery,
  useQueryState,
} from '@cynap/surface-sdk';
import './styles.css';
const ENTITY_TYPE = 'REPLACE_WITH_ENTITY_TYPE';
const PAGE_SIZE = 25;
type RecordRow = Record<string, unknown>;
const nameOf = (row: RecordRow) => String(row.name ?? row.id ?? 'Untitled');
const columns = [
  { accessorKey: 'name', header: 'Name', cell: ({ row }: { row: { original: RecordRow } }) => (
    <TooltipRoot><TooltipTrigger asChild><span className="tpl-truncate">{nameOf(row.original)}</span></TooltipTrigger>
      <TooltipContent>{nameOf(row.original)}</TooltipContent></TooltipRoot>
  ) },
  { accessorKey: 'stage', header: 'Status', cell: ({ row }: { row: { original: RecordRow } }) => <Badge tone="neutral" label={String(row.original.stage ?? 'Unassigned')} /> },
  { accessorKey: 'updated_at', header: 'Updated' },
];

function Queue() {
  const [page, setPage] = useQueryState('page', parseAsInteger, { defaultValue: 1, history: 'push' });
  const [sort, setSort] = useQueryState('sort', parseAsString);
  const [direction, setDirection] = useQueryState('dir', parseAsEnum(['asc', 'desc'] as const), { defaultValue: 'asc' });
  const [filters, setFilters] = useQueryState('filters', parseAsFilters, { defaultValue: [] });
  const [selectedId, setSelectedId] = useQueryState('selected', parseAsString);
  const current = Math.max(1, page ?? 1);
  const records = useEntityQuery(ENTITY_TYPE, {
    filters: filters ?? [], page: current, pageSize: PAGE_SIZE,
    ...(sort ? { sort: { field: sort, direction: direction === 'desc' ? 'desc' : 'asc' } } : {}),
  });
  const rows = records.data?.rows ?? [];
  const selected = rows.find((row) => String(row.id) === selectedId);
  const search = String(filters?.find((filter) => filter.field === 'name')?.value ?? '');
  function filterByName(value: string) {
    setFilters(value ? [{ field: 'name', operator: 'contains', value }] : []);
    setPage(1);
    setSelectedId(null);
  }
  return (
    <TooltipProvider>
      <Stack id="queue-page" config={{ gap: 24 }}>
        <PageHeader title="Work queue" description="Review the records that need your attention."
          actions={<Button onClick={records.refetch}>Refresh</Button>} />
        <FilterBar onReset={() => filterByName('')}>
          <Input aria-label="Filter by name" placeholder="Find a record" value={search} onChange={(event) => filterByName(event.target.value)} />
        </FilterBar>
        {records.isFetching && <Badge tone="info" label="Refreshing records…" />}
        {/* pattern:work-queue:start */}
        <Card><CardContent className="tpl-table-scroll">
          {records.state === 'loading' && rows.length === 0 ? <Skeleton primitiveKind="Table" height={320} />
          : records.state === 'error' || records.state === 'denied' ? <Stack id="queue-error" config={{ gap: 16 }}>
              <AlertCard severity="error" title="Records could not be loaded" description="Your work is unchanged." />
              <Button variant="outline" onClick={records.refetch}>Retry</Button>
            </Stack>
          : rows.length === 0 ? <EmptyState title="No matching records" description="Clear the filter to see the queue." action={{ label: 'Clear filter', onClick: () => filterByName('') }} />
          : <Table columns={columns} data={rows} interactive onSelect={(row) => setSelectedId(String(row.id))}
              isRowDisabled={() => records.isPreviousData}
              pagination={{ page: current, pageSize: PAGE_SIZE, total: records.data?.total ?? rows.length }}
              onPageChange={(next) => { setSelectedId(null); setPage(next); }}
              onSortChange={(next) => { setSort(next?.field ?? null); setDirection(next?.direction ?? null); setPage(1); setSelectedId(null); }} />}
        </CardContent></Card>
        <Sheet open={selected !== undefined} onOpenChange={(open) => { if (!open) setSelectedId(null); }}>
          <SheetContent className="tpl-detail-scroll" closeLabel="Close record detail">
            <SheetHeader><SheetTitle>{selected ? nameOf(selected) : 'Record'}</SheetTitle>
              <SheetDescription>Review the record without leaving your queue.</SheetDescription></SheetHeader>
            {selected && <Detail record={selected} clear={() => setSelectedId(null)} />}
          </SheetContent>
        </Sheet>
        {/* pattern:work-queue:end */}
      </Stack>
    </TooltipProvider>
  );
}

function Detail({ record, clear }: { record: RecordRow; clear: () => void }) {
  return (
    <Stack id="record-detail" config={{ gap: 24 }}>
      {/* pattern:long-text-review:start */}
      <Section title="Record notes" description="Long text stays in a reading container.">
        <Badge tone="info" label={String(record.stage ?? 'Unassigned')} />
        <Prose markdown={String(record.notes ?? 'No notes on this record yet.')} />
        <Button variant="outline" onClick={clear}>Back to the queue</Button>
      </Section>
      {/* pattern:long-text-review:end */}
    </Stack>
  );
}

/** Alternate master-detail pattern. Use instead of the Table/Sheet when a persistent pane helps. */
export function QueueMasterDetail({ rows }: { rows: readonly (RecordRow & { id: string })[] }) {
  return (
    <>
      {/* pattern:master-detail:start */}
      <SplitView items={rows} queryKey="selected" renderItem={nameOf}
        renderDetail={(record, { clear, inFilter }) => <Stack id="split-detail" config={{ gap: 16 }}>
          {!inFilter && <Badge tone="warning" label="Not in the current filter" />}
          <Detail record={record} clear={clear} />
        </Stack>}
        empty={<EmptyState title="Choose a record" description="Its notes and actions open here." />} />
      {/* pattern:master-detail:end */}
    </>
  );
}
const root = document.getElementById('root');
if (root) createRoot(root).render(<SurfaceApp info={{ name: 'work-queue', version: '1.0.0' }}><Queue /></SurfaceApp>);

